import "server-only";

import { parseServerEnvironment } from "./schema";

export function getServerEnvironment() {
  return parseServerEnvironment({
    NEXT_PUBLIC_APP_URL: process.env.NEXT_PUBLIC_APP_URL,
    NEXT_PUBLIC_SUPABASE_URL: process.env.NEXT_PUBLIC_SUPABASE_URL,
    NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY: process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY,
    NEXT_PUBLIC_TURNSTILE_SITE_KEY: process.env.NEXT_PUBLIC_TURNSTILE_SITE_KEY,
    SUPABASE_SECRET_KEY: process.env.SUPABASE_SECRET_KEY,
    CRON_SECRET: process.env.CRON_SECRET,
    WHATSAPP_APP_SECRET: process.env.WHATSAPP_APP_SECRET,
    WHATSAPP_WEBHOOK_VERIFY_TOKEN: process.env.WHATSAPP_WEBHOOK_VERIFY_TOKEN,
    GOOGLE_GENERATIVE_AI_API_KEY: process.env.GOOGLE_GENERATIVE_AI_API_KEY,
    GROQ_API_KEY: process.env.GROQ_API_KEY,
    AGENT_MODEL: process.env.AGENT_MODEL,
    AGENT_FALLBACK_MODEL: process.env.AGENT_FALLBACK_MODEL,
    AGENT_APPROVAL_SECRET: process.env.AGENT_APPROVAL_SECRET,
    AGENT_IP_HASH_SALT: process.env.AGENT_IP_HASH_SALT,
    AGENT_GUEST_DAILY_CAP: process.env.AGENT_GUEST_DAILY_CAP,
    AGENT_REAL_DATA_ENABLED: process.env.AGENT_REAL_DATA_ENABLED,
    AGENT_SCRIPTED_MODEL: process.env.AGENT_SCRIPTED_MODEL,
  });
}
